import{_ as a,o as d,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"向量表示与 Embedding","description":"理解向量、维度、Token Embedding、上下文化表示、相似度，以及生成模型内部表示与独立 Embedding 模型的区别。","frontmatter":{"title":"向量表示与 Embedding","description":"理解向量、维度、Token Embedding、上下文化表示、相似度，以及生成模型内部表示与独立 Embedding 模型的区别。","verified_at":"2026-07-28","sources":["https://developers.google.com/machine-learning/crash-course/embeddings","https://web.stanford.edu/~jurafsky/slp3/","https://arxiv.org/abs/1810.04805"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/foundations/model-principles/vector-representations-embeddings.md","filePath":"py-agent/foundations/model-principles/vector-representations-embeddings.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-principles/vector-representations-embeddings.md"};function r(o,e,s,l,h,b){return d(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="向量表示与-embedding" tabindex="-1">向量表示与 Embedding <a class="header-anchor" href="#向量表示与-embedding" aria-label="Permalink to &quot;向量表示与 Embedding&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Token ID 只是离散编号，编号 <code>105</code> 并不比 <code>104</code> 多一单位语义。神经网络需要连续数值才能通过矩阵运算学习关系，因此会把离散 Token 映射为向量。Embedding 是这种映射得到的表示，也是后续 Transformer 计算的起点。</p><p>本章只建立表示模型，不展开向量数据库、近似最近邻索引和 RAG。</p><h2 id="_1-向量是什么" tabindex="-1">1. 向量是什么 <a class="header-anchor" href="#_1-向量是什么" aria-label="Permalink to &quot;1. 向量是什么&quot;">​</a></h2><h3 id="_1-1-向量是有顺序的数值列表" tabindex="-1">1.1 向量是有顺序的数值列表 <a class="header-anchor" href="#_1-1-向量是有顺序的数值列表" aria-label="Permalink to &quot;1.1 向量是有顺序的数值列表&quot;">​</a></h3><p>一个三维示意向量可以写成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v = [0.12, -0.48, 0.91]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>真实模型常用数百到数千维。维度是坐标数量，不代表“模型知道多少个概念”。单个维度通常没有稳定的人类标签，语义分布在多个维度及其组合关系中。</p><h3 id="_1-2-连续空间允许学习关系" tabindex="-1">1.2 连续空间允许学习关系 <a class="header-anchor" href="#_1-2-连续空间允许学习关系" aria-label="Permalink to &quot;1.2 连续空间允许学习关系&quot;">​</a></h3><p>模型可以对向量做加权、投影、相加和非线性变换。训练会让对预测任务有类似作用的表示形成可利用的几何关系。这里的“接近”必须绑定具体模型、训练目标和相似度函数，不能理解成普遍语义真理。</p><h3 id="_1-3-向量值没有跨模型通用含义" tabindex="-1">1.3 向量值没有跨模型通用含义 <a class="header-anchor" href="#_1-3-向量值没有跨模型通用含义" aria-label="Permalink to &quot;1.3 向量值没有跨模型通用含义&quot;">​</a></h3><p>两个模型即使维度相同，坐标系也可能完全不同。不能直接混合不同 Embedding 模型产生的向量，也不能在模型升级后假设历史向量仍与新向量可比较。</p><h2 id="_2-token-embedding-矩阵" tabindex="-1">2. Token Embedding 矩阵 <a class="header-anchor" href="#_2-token-embedding-矩阵" aria-label="Permalink to &quot;2. Token Embedding 矩阵&quot;">​</a></h2><h3 id="_2-1-token-id-用来查表" tabindex="-1">2.1 Token ID 用来查表 <a class="header-anchor" href="#_2-1-token-id-用来查表" aria-label="Permalink to &quot;2.1 Token ID 用来查表&quot;">​</a></h3><p>设词表大小为 <code>V</code>，隐藏维度为 <code>D</code>，模型维护一个形状为 <code>V × D</code> 的 Embedding 矩阵 <code>E</code>。Token ID <code>i</code> 的初始表示就是矩阵第 <code>i</code> 行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token_id = i</span></span>
<span class="line"><span>embedding = E[i]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这不是从 ID 数值推导语义，而是用 ID 定位一组通过训练学到的参数。</p><h3 id="_2-2-embedding-参数随训练更新" tabindex="-1">2.2 Embedding 参数随训练更新 <a class="header-anchor" href="#_2-2-embedding-参数随训练更新" aria-label="Permalink to &quot;2.2 Embedding 参数随训练更新&quot;">​</a></h3><p>训练开始时向量通常没有成熟语义。预测损失通过反向传播影响 Embedding 和网络其他参数，使有用关系逐渐形成。Token Embedding 不是人工词典，也不是预先固定的语言规则。</p><h3 id="_2-3-初始表示还缺少上下文" tabindex="-1">2.3 初始表示还缺少上下文 <a class="header-anchor" href="#_2-3-初始表示还缺少上下文" aria-label="Permalink to &quot;2.3 初始表示还缺少上下文&quot;">​</a></h3><p>同一个 Token ID 每次查到相同的初始向量，但多义词在不同句子中含义不同。上下文差异不是查表阶段解决的，而是在 Transformer 多层计算后体现在每个位置的隐藏状态中。</p><h2 id="_3-位置信息" tabindex="-1">3. 位置信息 <a class="header-anchor" href="#_3-位置信息" aria-label="Permalink to &quot;3. 位置信息&quot;">​</a></h2><h3 id="_3-1-只有-token-向量无法表示顺序" tabindex="-1">3.1 只有 Token 向量无法表示顺序 <a class="header-anchor" href="#_3-1-只有-token-向量无法表示顺序" aria-label="Permalink to &quot;3.1 只有 Token 向量无法表示顺序&quot;">​</a></h3><p>“猫追狗”和“狗追猫”包含相同词项，但顺序决定不同语义。Transformer 的注意力计算本身需要额外位置信息来区分位置。</p><h3 id="_3-2-位置表示进入序列计算" tabindex="-1">3.2 位置表示进入序列计算 <a class="header-anchor" href="#_3-2-位置表示进入序列计算" aria-label="Permalink to &quot;3.2 位置表示进入序列计算&quot;">​</a></h3><p>模型可能使用可学习位置向量、正弦位置编码、旋转位置编码等方案。具体机制不同，目标相同：让表示包含 Token 内容和相对或绝对位置信息。</p><p>位置方案会影响模型能处理的长度和对远距离关系的表现，但不能把“更大位置范围”简单等同于“完美利用长上下文”。</p><h2 id="_4-静态表示与上下文化表示" tabindex="-1">4. 静态表示与上下文化表示 <a class="header-anchor" href="#_4-静态表示与上下文化表示" aria-label="Permalink to &quot;4. 静态表示与上下文化表示&quot;">​</a></h2><h3 id="_4-1-初始-token-embedding-是查表结果" tabindex="-1">4.1 初始 Token Embedding 是查表结果 <a class="header-anchor" href="#_4-1-初始-token-embedding-是查表结果" aria-label="Permalink to &quot;4.1 初始 Token Embedding 是查表结果&quot;">​</a></h3><p>假设“bank”出现在两个句子中：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I deposited money at the bank.</span></span>
<span class="line"><span>We sat on the river bank.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>分词结果相同时，“bank”的初始 Token Embedding 相同。</p><h3 id="_4-2-隐藏状态结合了上下文" tabindex="-1">4.2 隐藏状态结合了上下文 <a class="header-anchor" href="#_4-2-隐藏状态结合了上下文" aria-label="Permalink to &quot;4.2 隐藏状态结合了上下文&quot;">​</a></h3><p>经过 Attention 和前馈层后，每个位置的表示吸收其他相关位置的信息。金融语境中的“bank”和河岸语境中的“bank”会形成不同的上下文化隐藏状态。</p><table tabindex="0"><thead><tr><th>表示</th><th>是否依赖当前上下文</th><th>主要位置</th></tr></thead><tbody><tr><td>Token Embedding</td><td>否</td><td>模型输入查表</td></tr><tr><td>位置表示</td><td>依赖位置</td><td>模型输入或注意力计算</td></tr><tr><td>隐藏状态</td><td>是</td><td>Transformer 各层输出</td></tr><tr><td>文本 Embedding</td><td>取决于专用模型</td><td>检索、聚类等外部任务</td></tr></tbody></table><h3 id="_4-3-一个词的向量-常常指代不清" tabindex="-1">4.3 “一个词的向量”常常指代不清 <a class="header-anchor" href="#_4-3-一个词的向量-常常指代不清" aria-label="Permalink to &quot;4.3 “一个词的向量”常常指代不清&quot;">​</a></h3><p>讨论时应明确是词表中的输入 Embedding、某一层某个位置的隐藏状态，还是独立 Embedding API 返回的整段文本向量。它们的形状、目标和可比较性都不同。</p><h2 id="_5-整段文本的-embedding" tabindex="-1">5. 整段文本的 Embedding <a class="header-anchor" href="#_5-整段文本的-embedding" aria-label="Permalink to &quot;5. 整段文本的 Embedding&quot;">​</a></h2><h3 id="_5-1-文本向量压缩一个序列" tabindex="-1">5.1 文本向量压缩一个序列 <a class="header-anchor" href="#_5-1-文本向量压缩一个序列" aria-label="Permalink to &quot;5.1 文本向量压缩一个序列&quot;">​</a></h3><p>检索和聚类通常需要每段文本对应一个固定长度向量。专用 Embedding 模型会把整段输入编码成单个向量，可能使用特殊汇聚位置、池化或专门训练目标。</p><h3 id="_5-2-生成模型内部状态不等于-embedding-api" tabindex="-1">5.2 生成模型内部状态不等于 Embedding API <a class="header-anchor" href="#_5-2-生成模型内部状态不等于-embedding-api" aria-label="Permalink to &quot;5.2 生成模型内部状态不等于 Embedding API&quot;">​</a></h3><p>生成模型为了预测下一个 Token 产生每个位置的隐藏状态；Embedding 模型为了让文本可比较而优化固定向量。即使架构有相似部分，也不能把生成响应中的任意内部状态当成稳定检索向量。</p><h3 id="_5-3-输入单位影响向量含义" tabindex="-1">5.3 输入单位影响向量含义 <a class="header-anchor" href="#_5-3-输入单位影响向量含义" aria-label="Permalink to &quot;5.3 输入单位影响向量含义&quot;">​</a></h3><p>一句话、一个段落和一整份文档包含的信息密度不同。把过长文本压进单个向量可能掩盖局部主题；切得过碎又丢失上下文。如何切分属于检索系统设计，不是 Embedding 数值本身自动解决的问题。</p><h2 id="_6-相似度" tabindex="-1">6. 相似度 <a class="header-anchor" href="#_6-相似度" aria-label="Permalink to &quot;6. 相似度&quot;">​</a></h2><h3 id="_6-1-余弦相似度比较方向" tabindex="-1">6.1 余弦相似度比较方向 <a class="header-anchor" href="#_6-1-余弦相似度比较方向" aria-label="Permalink to &quot;6.1 余弦相似度比较方向&quot;">​</a></h3><p>对向量 <code>a</code> 和 <code>b</code>，余弦相似度为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cos(a, b) = (a · b) / (||a|| × ||b||)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它比较向量方向，范围通常在 <code>-1</code> 到 <code>1</code>。越大一般表示在该模型空间中越相似，但阈值必须用真实任务数据确定。</p><h3 id="_6-2-点积与欧氏距离有不同假设" tabindex="-1">6.2 点积与欧氏距离有不同假设 <a class="header-anchor" href="#_6-2-点积与欧氏距离有不同假设" aria-label="Permalink to &quot;6.2 点积与欧氏距离有不同假设&quot;">​</a></h3><table tabindex="0"><thead><tr><th>度量</th><th>关注点</th><th>需要注意</th></tr></thead><tbody><tr><td>余弦相似度</td><td>方向</td><td>忽略整体长度</td></tr><tr><td>点积</td><td>方向与长度</td><td>向量模长会影响分数</td></tr><tr><td>欧氏距离</td><td>空间距离</td><td>量纲与归一化影响结果</td></tr></tbody></table><p>如果向量已经单位归一化，余弦、点积和欧氏距离的排序存在紧密关系；未归一化时不能随意互换。应遵循 Embedding 模型文档和索引配置。</p><h3 id="_6-3-相似不等于蕴含或事实一致" tabindex="-1">6.3 相似不等于蕴含或事实一致 <a class="header-anchor" href="#_6-3-相似不等于蕴含或事实一致" aria-label="Permalink to &quot;6.3 相似不等于蕴含或事实一致&quot;">​</a></h3><p>“这款药有效”和“这款药无效”共享大量词汇和主题，向量可能很接近，但结论相反。Embedding 相似度适合召回候选，不足以替代否定识别、事实核验或业务规则。</p><h2 id="_7-表示的能力与限制" tabindex="-1">7. 表示的能力与限制 <a class="header-anchor" href="#_7-表示的能力与限制" aria-label="Permalink to &quot;7. 表示的能力与限制&quot;">​</a></h2><h3 id="_7-1-表示服务于训练目标" tabindex="-1">7.1 表示服务于训练目标 <a class="header-anchor" href="#_7-1-表示服务于训练目标" aria-label="Permalink to &quot;7.1 表示服务于训练目标&quot;">​</a></h3><p>向量保留哪些信息，取决于模型数据和目标。为通用语义检索训练的模型，不一定擅长代码克隆、法律引用或极短产品编号匹配。任务适配必须通过样例评测，而不是只看维度。</p><h3 id="_7-2-维度更高不自动更好" tabindex="-1">7.2 维度更高不自动更好 <a class="header-anchor" href="#_7-2-维度更高不自动更好" aria-label="Permalink to &quot;7.2 维度更高不自动更好&quot;">​</a></h3><p>更高维度提供更大表示容量，也增加存储和计算。质量还受训练数据、目标、输入长度和领域匹配影响。</p><h3 id="_7-3-坐标不能直接当作解释" tabindex="-1">7.3 坐标不能直接当作解释 <a class="header-anchor" href="#_7-3-坐标不能直接当作解释" aria-label="Permalink to &quot;7.3 坐标不能直接当作解释&quot;">​</a></h3><p>观察某一维数值高低，通常不能给出可靠语义解释。向量相似也只是模型空间中的信号，不能为最终决策提供独立审计依据。</p><h2 id="_8-常见误解" tabindex="-1">8. 常见误解 <a class="header-anchor" href="#_8-常见误解" aria-label="Permalink to &quot;8. 常见误解&quot;">​</a></h2><h3 id="_8-1-token-id-本身包含语义" tabindex="-1">8.1 “Token ID 本身包含语义” <a class="header-anchor" href="#_8-1-token-id-本身包含语义" aria-label="Permalink to &quot;8.1 “Token ID 本身包含语义”&quot;">​</a></h3><p>ID 是词表索引，语义关系来自被索引的 Embedding 和后续计算。</p><h3 id="_8-2-embedding-就是-transformer-的最终答案" tabindex="-1">8.2 “Embedding 就是 Transformer 的最终答案” <a class="header-anchor" href="#_8-2-embedding-就是-transformer-的最终答案" aria-label="Permalink to &quot;8.2 “Embedding 就是 Transformer 的最终答案”&quot;">​</a></h3><p>Embedding 是表示。生成模型还需经过多层变换并投影成下一个 Token 分布。</p><h3 id="_8-3-向量最接近的文本就是正确答案" tabindex="-1">8.3 “向量最接近的文本就是正确答案” <a class="header-anchor" href="#_8-3-向量最接近的文本就是正确答案" aria-label="Permalink to &quot;8.3 “向量最接近的文本就是正确答案”&quot;">​</a></h3><p>接近表示模型认为两段输入在训练目标下相似。最终答案仍需上下文理解、来源判断和业务验证。</p><h2 id="_9-自测" tabindex="-1">9. 自测 <a class="header-anchor" href="#_9-自测" aria-label="Permalink to &quot;9. 自测&quot;">​</a></h2><ol><li>为什么 Token ID 不能直接参与语义距离计算？</li><li>Token Embedding 矩阵的两条轴分别表示什么？</li><li>同一个多义词怎样在不同句子中形成不同表示？</li><li>生成模型隐藏状态与独立文本 Embedding 有什么区别？</li><li>为什么余弦相似度高不能证明两个陈述事实一致？</li></ol><p>能够区分“词表索引、初始向量、上下文化隐藏状态、整段文本向量”，就不会把所有 Embedding 概念混成一种 API。</p>`,72)])])}const m=a(i,[["render",r]]);export{c as __pageData,m as default};
